// Generate one Astro page per mirrored WordPress page.
import fs from 'node:fs/promises';
import path from 'node:path';

const PROJECT = path.resolve(import.meta.dirname, '..');
const pages = JSON.parse(await fs.readFile(path.join(PROJECT, 'src/data/wp-pages.json'), 'utf8'));

/**
 * wp-pages.json is shared. Archives, posts and the `__post__` style bundle add
 * their own keys, and those are not top-level pages: their partials live in
 * subdirectories and their routes are generated by their own scripts. Emitting
 * `src/pages/<key>.astro` for them produces routes whose imports do not resolve.
 */
const isTopLevelPage = key =>
  key !== '__post__' &&
  !key.startsWith('archive-') &&
  !key.startsWith('post-') &&
  // Anything carrying its own route is placed by the script that mirrored it.
  (key === 'index' || !pages[key].route);

const written = [];
for (const slug of Object.keys(pages).filter(isTopLevelPage)) {
  const file = slug === 'index' ? 'index.astro' : `${slug}.astro`;
  const body = `---
import WpLayout from '../layouts/WpLayout.astro';
import content from '../partials/${slug}.html?raw';
---

<WpLayout slug="${slug}">
  <Fragment set:html={content} />
</WpLayout>
`;
  await fs.writeFile(path.join(PROJECT, 'src/pages', file), body, 'utf8');
  written.push(file);
}

process.stdout.write(`generated ${written.length} pages:\n${written.join('\n')}\n`);
